import { createCallerFactory, appRouter } from './trpc';

// Create a server-side caller using createCallerFactory
export const caller = createCallerFactory(appRouter);

import ClientComponent from './ClientComponent';
import { caller } from '../server/caller';

export default async function Page() {
  const serverData = await caller.hello({ name: 'Server' });

  return (
    <div>
      <h1 id="server-data">{serverData}</h1>
      <ClientComponent />
    </div>
  );
}

'use client';

import { trpc } from '../utils/trpc';

export default function ClientComponent() {
  const { data, isLoading } = trpc.hello.useQuery({ name: 'Client' });

  return (
    <p id="client-data">
      {isLoading ? 'Loading...' : data}
    </p>
  );
}

